def next_field(line, start):
    """Reads a single field from the CSV line starting at index start.
    Returns (field, next_start) where field is the field value with quotes removed and doubled quotes turned into one,
    and next_start is the index right after the separating comma, or -1 if at the end of the line.
    """
    if start >= len(line):
        return None, -1

    if line[start] != '"':
        end = line.find(',', start)
        if end == -1:
            end = len(line)
        return line[start:end], end + 1

    start += 1
    end = start
    while True:
        if end >= len(line):
            raise ValueError("Unterminated quoted field")
        if line[end] == '"':
            if end + 1 < len(line) and line[end + 1] == '"':
                end += 2
            else:
                break
        end += 1

    return line[start:end].replace('""', '"'), end + 2
```

