def next_field(line, start):
    """Read one field of line beginning at index start.

    It returns (field, next_start), where field has its wrapping quotes removed
    and doubled quotes turned into one, and next_start is the index just after the
    separating comma, or -1 at the end.
    """
    n = len(line)
    if start >= n:
        return None, -1

    if line[start] != '"':
        end = line.find(',', start)
        if end == -1:
            field = line[start:]
            next_start = n
        else:
            field = line[start:end]
            next_start = end + 1
    else:
        end = start + 1
        while end < n:
            if line[end] == '"':
                if end + 1 < n and line[end + 1] == '"':
                    end += 2
                else:
                    break
            end += 1
        if end == n:
            raise ValueError("Unmatched quote in field")
        field = line[start + 1:end].replace('""', '"')
        next_start = end + 2

    return field, next_start
