    if start >= n:
        return None, -1

    if line[start] != '"':
        # Unquoted field
        end = line.find(',', start)
        if end == -1:
            field = line[start:]
            next_start = n
        else:
            field = line[start:end]
            next_start = end + 1
    else:
        # Quoted field
        start += 1
        end = start
        while end < n:
            if line[end] == '"':
                if end + 1 < n and line[end + 1] == '"':
                    end += 1
                else:
                    break
            end += 1

        if end == n:
            raise ValueError("Unclosed quote in field")

        field = line[start:end].replace('""', '"')
        next_start = end + 2

    return field, next_start
