def next_field(line, start):
    n = len(line)
    if start >= n:
        return None, -1

    in_quotes = False
    field = []
    i = start

    while i < n:
        if line[i] == '"':
            if i + 1 < n and line[i + 1] == '"':
                field.append('"')
                i += 2
            elif in_quotes and i == n - 1:
                return ''.join(field), -1
            elif not in_quotes:
                in_quotes = True
                i += 1
            else:
                break
        elif line[i] == ',' and not in_quotes:
            break
        else:
            field.append(line[i])
            i += 1

    if in_quotes:
        raise ValueError("Unmatched quotes in field")

    return ''.join(field), i + 1
