def next_field(line, start):
    field = []
    in_quotes = False
    for i in range(start, len(line)):
        if line[i] == '"':
            if in_quotes:
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            elif i == start:
                in_quotes = True
            else:
                break
        else:
            if in_quotes:
                field.append(line[i])
            else:
                break
    else:
        i += 1
    if in_quotes:
        raise ValueError("Unterminated quoted field")
    return ''.join(field), i
